arguments.command:
cd /workspace && python3 - <<'EOF'
import os, stat
root = '/workspace/submission'
# remove generated caches
removed = []
for base, dirs, files in os.walk(root, followlinks=False):
    for name in list(dirs):
        if name in ('__pycache__', '.pytest_cache', '.ruff_cache', '.git'):
            p = os.path.join(base, name)
            import shutil; shutil.rmtree(p); removed.append(p)
print('removed:', removed)
count = size = 0
for base, dirs, files in os.walk(root, followlinks=False):
    for name in dirs + files:
        p = os.path.join(base, name)
        st = os.lstat(p)
        count += 1
        if stat.S_ISREG(st.st_mode):
            size += st.st_size
            print(' file', os.path.relpath(p, root), st.st_size, oct(st.st_mode), 'links', st.st_nlink)
        else:
            print(' dir ', os.path.relpath(p, root))
        assert stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode), p
print('entries:', count, 'bytes:', size)
assert count <= 4096 and size <= 64*1024**2
EOF
